function emptyStateHtml(){
  /* 两态：
     ① 还没读到任何章节、也没报错 → 这是"正在加载"（正常路径，几百毫秒），
        给一块有节奏的骨架，而不是一句"内容还在生成中"让人以为坏了；
     ② 有错误 → 老老实实列出来，并给一个重新载入的按钮。 */
  if (!S.loadErrors.length){
    return '<div class="emptyCard loadCard">' +
      '<div class="loadOrb" aria-hidden="true"><i></i></div>' +
      "<h2>正在准备讲义</h2>" +
      '<p class="loadSub">读取章节数据与学习进度…</p>' +
      '<div class="skel" aria-hidden="true">' +
        '<span style="width:34%"></span><span style="width:96%"></span>' +
        '<span style="width:88%"></span><span style="width:72%"></span>' +
        '<span style="width:52%"></span>' +
      "</div></div>";
  }
  var errs = '<ul class="errList">' + S.loadErrors.slice(0, 6).map(function(e){
      return "<li><code>" + escapeHtml(e) + "</code></li>"; }).join("") + "</ul>";
  return '<div class="emptyCard"><div class="emptyIco">📭</div>' +
    "<h2>还没读到内容</h2>" +
    "<p>不到 <code>content/chNN.json</code>。内容管道还没跑完，或者这份内容层不完整。<br>" +
    "跑完之后点下面按钮（或按 F5）就有卡片了。</p>" + errs +
    '<button class="primary" data-act="reload">🔄 重新载入</button></div>';
}
